import{K as t,a as i,c as l,b as a,k as n,q as c,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 修订、批注、比较与定稿","description":"在 Word 中跟踪修改、提出批注、逐条接受或拒绝修订、比较两个版本，并检查定稿中的隐藏标记和文档属性。","frontmatter":{"title":"Word 修订、批注、比较与定稿","description":"在 Word 中跟踪修改、提出批注、逐条接受或拒绝修订、比较两个版本，并检查定稿中的隐藏标记和文档属性。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"在 Word 中跟踪修改、提出批注、逐条接受或拒绝修订、比较两个版本，并检查定稿中的隐藏标记和文档属性。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 图片、题注、交叉引用与参考文献","link":"/tools/office/word/images-references"},"next":{"text":"Word 邮件合并、批量通知与标签","link":"/tools/office/word/mail-merge"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 图片、题注、交叉引用与参考文献","link":"/tools/office/word/images-references"},"next":{"text":"Word 邮件合并、批量通知与标签","link":"/tools/office/word/mail-merge"}},"headers":[],"relativePath":"tools/office/word/review.md","filePath":"tools/office/word/review.md"}'),d={name:"tools/office/word/review.md"},k=Object.assign(d,{setup(h){const o={path:"/tools/office/word/review",app:"Word",title:"从修订稿得到真正的定稿",steps:[{tab:"审阅",command:"修订",setting:"开启修订；显示：所有标记",anchor:"walkthrough-1"},{tab:"审阅",command:"新建批注",setting:"选中相关文字；说明问题与建议",anchor:"walkthrough-2"},{tab:"审阅",command:"接受 / 拒绝",setting:"逐条确认；检查批注；关闭修订",anchor:"walkthrough-3"}]};return(p,e)=>{const r=t("OfficeGuide");return i(),l("div",null,[e[0]||(e[0]=a("h1",{id:"word-修订、批注、比较与定稿",tabindex:"-1"},[n("Word 修订、批注、比较与定稿 "),a("a",{class:"header-anchor",href:"#word-修订、批注、比较与定稿","aria-label":'Permalink to "Word 修订、批注、比较与定稿"'},"​")],-1)),e[1]||(e[1]=a("p",null,"审阅的目标是清楚区分“原文、建议、讨论和已确认的结果”。协作开始前约定谁负责定稿，避免多个人分别接受所有修订后再互相覆盖。",-1)),c(r,{guide:o}),e[2]||(e[2]=s('<h2 id="track" tabindex="-1">开始一次可追踪的审阅 <a class="header-anchor" href="#track" aria-label="Permalink to &quot;开始一次可追踪的审阅 {#track}&quot;">​</a></h2><p>保存工作文件，进入“审阅 → 修订”。根据目标环境选择跟踪所有人的修改或自己的修改，然后改一个词、删除一句话、补一段说明，确认界面出现修订标记。仅打开“显示标记”并不一定意味着正在跟踪新修改，要检查修订开关。</p><p>简单标记适合阅读正文，所有标记适合逐项核对；无标记只是隐藏显示，<strong>不表示删除的文字或修改记录已被清除</strong>。原始状态也只是另一种查看方式。<a href="https://support.microsoft.com/en-us/word/training/track-changes-in-word" target="_blank" rel="noopener noreferrer">微软修订说明</a></p><h2 id="comments" tabindex="-1">用批注解释问题 <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;用批注解释问题 {#comments}&quot;">​</a></h2><p>选中相关文字，点击“新建批注”，写清楚具体问题和希望对方做的决定。例如“这里的完成率分母是全部任务还是本月到期任务，请补充口径”。不要只写“有问题”，也不要用批注代替正文里必须给读者的解释。</p><p>回复和解决批注用于推进讨论；解决通常不等于永久删除，历史仍可能保留。提及他人可能触发通知，因此只在需要对方处理时使用。准备外发时检查批注和讨论是否适合随文件交付。</p><h2 id="decide" tabindex="-1">接受或拒绝修改 <a class="header-anchor" href="#decide" aria-label="Permalink to &quot;接受或拒绝修改 {#decide}&quot;">​</a></h2><ol><li>将显示模式切为所有标记，清除仅查看某个人或某类修改的筛选。</li><li>使用“上一处/下一处”逐条查看修改。</li><li>对已确认建议选择接受；不同意则拒绝，必要时补充批注说明。</li><li>大范围调整先检查相关内容，不能只凭“修改很多”就全部接受。</li><li>全文核对后关闭修订，再检查是否还有未处理条目。</li></ol><p>“接受所有显示的修订”可能只处理当前筛选中可见的内容；不要把它等同于处理整个文档。关闭修订也不会自动接受已经存在的修改。</p><h2 id="compare" tabindex="-1">比较两份文件 <a class="header-anchor" href="#compare" aria-label="Permalink to &quot;比较两份文件 {#compare}&quot;">​</a></h2><p>若对方直接改了文件、没有开修订，使用“审阅 → 比较”，分别选择原始版本和修订版本。检查比较选项是否包含格式、批注等需要的范围，通常把结果显示在新文档中，保留两个输入文件。</p><p>比较结果需要人工判断：段落移动、样式变化或大量复制粘贴可能产生较多差异。合并用于整合多个审阅版本，也不能代替业务决策。每次合并后确认章节是否重复、图表是否错位、目录是否仍指向正确标题。</p><h2 id="finalize" tabindex="-1">定稿与外发 <a class="header-anchor" href="#finalize" aria-label="Permalink to &quot;定稿与外发 {#finalize}&quot;">​</a></h2><p>在最终副本上处理修订和批注，检查“文件 → 信息 → 检查问题 → 检查文档”中可发现的属性、隐藏内容等；具体项目依版本而异。检查器是辅助，仍要人工查看页眉页脚、嵌入对象、链接和附件。</p><p>随后更新目录与交叉引用，保存源文件，导出不包含不必要修订标记的 PDF，再打开 PDF 复查。需要保留完整审阅过程时，把审阅稿单独归档，不把“审阅稿”和“外发稿”混成同一个版本名。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>建立原稿和修订稿：改一句话、删除一段、增加一条批注。在无标记视图下确认画面看起来干净，再切回所有标记，理解记录仍存在。接受第一处修改、拒绝第二处，处理批注，导出 PDF，检查输出是否只包含已确定内容。</p><h2 id="walkthrough" tabindex="-1">图示跟做：从修订稿得到真正的定稿 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：从修订稿得到真正的定稿 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：记录三种不同修改 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：记录三种不同修改 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：审阅 → 修订。</strong></p><p>另存一份练习副本，选择“审阅 → 修订”。改一个日期、删除一段、增加一句说明，再切到所有标记查看。审阅显示方式只控制看见哪些标记，并不决定这些修改是否已接受。多人协作时明确本轮谁负责最终确认。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：把疑问挂到具体位置 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：把疑问挂到具体位置 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：审阅 → 新建批注。</strong></p><p>选中需要确认的句子，新增批注，写“这里的金额口径是否只包含已完成订单？建议附日期范围”。一个批注解决一个问题，并给出可操作的下一步。批注中的讨论与对正文的修订是两类对象，处理完一个不代表另一个也消失。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：生成可交付的最终版本 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：生成可交付的最终版本 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：审阅 → 接受 / 拒绝。</strong></p><p>逐条移动到修改位置，根据原意接受或拒绝；检查完成后关闭修订，并按交付要求处理批注。保存、关闭再重开，切回所有标记，确认没有遗留。再导出阅读版 PDF，检查是否意外带出审阅气泡或作者信息；需要留审阅记录时另存单独版本。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>“无标记”不等于没有修订。交付前不能只看屏幕干净，还应检查审阅窗格及文档检查结果；对于“全部接受”应先明确每个修改的含义。</p>',30))])}}});export{u as __pageData,k as default};
